      if (!equal(token, config.adminSecret))
        throw new HttpError(403, 'Invalid administrator credential.');
    50|      if (url.pathname === '/admin/reset' && req.method === 'POST') {
        seedBank();
        reply(200, { ok: true });
        return;
      }
