    90|      reply(
        200,
        db
          .prepare('SELECT id,userId,label,iban FROM accounts WHERE userId!=? ORDER BY userId')
          .all(actor)
          .map((a: any) => ({ ...a, name: person(a.userId)?.name })),
      );
      return;
    }
    if (url.pathname === '/v1/movements' && req.method === 'GET') {
   100|      reply(
        200,
        db
          .prepare(
