export const actionRoutes = [
  defineRoute('POST', 'actions', 'any', async ({ json, current, body }) => {
    const parsed = z
      .object({
        name: z.enum([
          'transfer_money',
          'confirm_transfer',
          'request_human',
          'operation_status',
          'list_accounts',
          'search_documents',
        ]),
        arguments: z.unknown(),
        conversationId: z.string().nullable().optional(),
        intentId: z.string().max(150).optional(),
      })
      .parse(await body());
