    return json(
      await transferMoney(
        {
          userId: current!.id,
          conversationId: intent.conversation_id,
          runId: randomUUID(),
          intentId: intent.id,
          approvalId: approval.id,
          confirmedBy: 'click' as const,
        },
        JSON.parse(approval.payload),
      ),
    );
  }),
];

