        <select
          aria-label="Conversation"
          value={conversationId || ''}
          onChange={(e) => onOpen(e.target.value)}
        >
          <option value="">New conversation</option>
          {conversations.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title}
            </option>
          ))}
        </select>
      </label>
      <section className="chat-panel">
        <div className="chat-header">
          <span className="assistant-avatar">✧</span>
          <div>
            <strong>Banana Bank assistant</strong>
            <small>
              <span className="live-dot" /> Here to help
            </small>
          </div>
          <span className="subtle-tag">{name.split(' ')[0]}</span>
        </div>
        <div className="messages">
          {!messages.length && (
            <div className="chat-empty">
              <span className="big-sparkle">✧</span>
              <h2>What do you need today?</h2>
              <p>Start with your accounts or a question.</p>
              <div className="suggestions">
                {[
                  'What are the balances of my accounts?',
                  'When is the Aurora account fee waived?',
                  'I want to speak to a person',
                ].map((s) => (
                  <button key={s} disabled={busy} onClick={() => onSend(s)}>
                    {s}
                    <span>↗</span>
                  </button>
                ))}
              </div>
            </div>
          )}
          {messages.map((m, i) => (
            <div className={`message ${m.role}`} key={m.id || i}>
              {m.role === 'assistant' && <span className="message-avatar">✧</span>}
              <div className="bubble">
                <div>
                  {String(m.content)
                    .split(/(\*\*[^*]+\*\*)/g)
                    .map((part, j) =>
                      part.startsWith('**') && part.endsWith('**') ? (
                        <strong key={j}>{part.slice(2, -2)}</strong>
                      ) : (
                        part
                      ),
                    )}
                </div>
                <small>{date(m.created_at)}</small>
              </div>
            </div>
          ))}
          {busy && (
            <div className="message assistant">
              <span className="message-avatar">✧</span>
              <div className="thinking">
                <i />
                <i />
                <i />
                <span>Checking…</span>
              </div>
            </div>
          )}
          <div ref={messagesEnd} />
        </div>
        <form
          className="composer"
          onSubmit={(e) => {
            e.preventDefault();
            onSend();
          }}
        >
          <textarea
            aria-label="Message the assistant"
            placeholder="What can we help with?"
            value={text}
            onChange={(e) => onText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                onSend();
              }
            }}
            rows={2}
          />
          <button aria-label="Send message" disabled={busy || !text.trim()}>
            <Icon name="arrow" />
          </button>
        </form>
        <div className="chat-footnote">
          AI assistant · Check important details before taking action.
        </div>
      </section>
    </div>
  );
}

import type { AnyRecord } from '../lib/api';
import { money } from '../lib/format';
import Icon from './Icon';

export default function TransferTab({
  dashboard,
  from,
  to,
  amount,
  concept,
  busy,
  setFrom,
  setTo,
  setAmount,
  setConcept,
  onSubmit,
  onOverview,
}: {
  dashboard: AnyRecord;
  from: string;
  to: string;
  amount: string;
  concept: string;
  busy: boolean;
  setFrom: (v: string) => void;
  setTo: (v: string) => void;
  setAmount: (v: string) => void;
  setConcept: (v: string) => void;
  onSubmit: () => void;
  onOverview: () => void;
}) {
  return (
    <>
      <div className="page-heading">
        <div>
          <div className="eyebrow">FROM ONE ACCOUNT TO ANOTHER</div>
          <h1>Transfers</h1>
          <p>Send money to another account in this environment.</p>
        </div>
      </div>
      <div className="transfer-layout">
        <form
          className="panel transfer-form"
          onSubmit={(e) => {
            e.preventDefault();
            onSubmit();
          }}
        >
          <h2>Your transfer details</h2>
          <label>
            From account
            <select value={from} onChange={(e) => setFrom(e.target.value)} required>
              {dashboard.accounts?.map((a: AnyRecord) => (
                <option key={a.id} value={a.id}>
                  {a.label} · {a.id} · {money(a.balanceCents)}
                </option>
              ))}
            </select>
          </label>
          <label>
            Recipient
            <select value={to} onChange={(e) => setTo(e.target.value)} required>
              <option value="">Select an account</option>
              {dashboard.contacts?.map((a: AnyRecord) => (
                <option key={a.id} value={a.id}>
                  {a.name} · {a.label} · {a.id}
                </option>
              ))}
            </select>
          </label>
          <label>
            Amount in euros
            <div className="amount-input">
              <input
                aria-label="Amount in euros"
                type="number"
                step="0.01"
                min="0.01"
                max="100000"
                required
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
              />
              <span>EUR</span>
            </div>
          </label>
          <label>
            Description
            <input
              value={concept}
              onChange={(e) => setConcept(e.target.value)}
              placeholder="What is this transfer for?"
              maxLength={200}
              required
            />
          </label>
          <button className="primary-button" disabled={busy}>
            {busy ? 'Processing…' : 'Send transfer'}
            <Icon name="arrow" />
          </button>
        </form>
        <aside className="transfer-note">
          <Icon name="transfer" />
          <h2>
            It is all in
            <br />
            your activity.
          </h2>
          <p>
            Check your activity to see the status of your transfers. If you have any questions, the
            assistant can help.
          </p>
          <button className="text-button" onClick={onOverview}>
            View my accounts ↗
          </button>
        </aside>
      </div>
    </>
  );
}
